section.sourcecode:
SSHKEY DEFINITIONS ::= BEGIN
SshKeyCtx ::= SEQUENCE { user [0] OCTET STRING OPTIONAL , key [1] OCTET STRING OPTIONAL , h [2] OCTET STRING OPTIONAL }
EncCtx ::= SEQUENCE { encPart [0] OCTET STRING }
SshKeyUserAuth ::= SEQUENCE { username [0] OCTET STRING , keytype [1] OCTET STRING , key [2] OCTET STRING , sigtype [3] OCTET STRING , sig [4] OCTET STRING }
EncSshKeyUserAuth ::= OCTET STRING
SshKeyHostAuth ::= SEQUENCE { keytype [0] OCTET STRING , key [1] OCTET STRING , sigtype [2] OCTET STRING , sig [3] OCTET STRING }
SshKeyKEX ::= SEQUENCE { kextypes [0] OCTET STRING , enctypes [1] OCTET STRING , sigtypes [2] OCTET STRING , kextype [3] OCTET STRING OPTIONAL , pk [4] OCTET STRING OPTIONAL , enctype [5] OCTET STRING OPTIONAL }
SshKeyServerContext ::= SEQUENCE { initiatorPk [0] OCTET STRING OPTIONAL , acceptorPk [1] OCTET STRING , sessionKey [2] OCTET STRING OPTIONAL , initiatorSigtypes [3] OCTET STRING OPTIONAL , acceptorSigtypes [4] OCTET STRING , acceptorSk [5] OCTET STRING OPTIONAL }
SshKeyStatus ::= INTEGER { SSH-KEY-COMPLETE (1) , SSH-KEY-CONTINUE-NEEDED (2) , SSH-KEY-FAILURE (3) }
SshKeyToken ::= SEQUENCE { status [0] SshKeyStatus , kex [1] SshKeyKEX OPTIONAL , hostauth [2] SshKeyHostAuth OPTIONAL , encuserauth [3] EncSshKeyUserAuth OPTIONAL , cctx [4] EncCtx OPTIONAL , sctx [5] EncCtx OPTIONAL }
END
